"use client";

import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from "react";
import styles from "./logistics.module.css";

type SystemTab = "dashboard" | "requests" | "approval" | "routes" | "documents" | "reports" | "directories" | "admin";
type RequestStatus = "Черновик" | "На согласовании" | "Возвращена" | "Согласована" | "Завершена";
type FieldType = "text" | "number" | "date" | "datetime" | "textarea" | "select" | "checkbox";
type SectionType = "form" | "table" | "dashboard";
type ActionType = "add" | "export" | "custom";
type ModalKind =
  | "request"
  | "user"
  | "place"
  | "tariff"
  | "template"
  | "settings"
  | "monthly"
  | "route"
  | "preview"
  | "builder-tab"
  | "builder-section"
  | "builder-field"
  | "builder-action"
  | "builder-role"
  | "custom-record"
  | null;

type UserRow = { id: string; name: string; login: string; role: string; active: boolean; terminationDate: string; archived: boolean };
type PlaceRow = { id: string; name: string; category: string; manual: boolean; active: boolean };
type TariffRow = { id: string; name: string; category: string; dayRate: number; nightRate: number; oneDayRate: number; active: boolean };
type TemplateRow = { id: string; name: string; type: string; version: string; effectiveFrom: string; active: boolean; fileName: string; mimeType: string; dataUrl: string; usedCount: number };
type RequestRow = { id: string; number: string; author: string; route: string; purpose: string; departureAt: string; returnAt: string; driver: string; vehicle: string; status: RequestStatus; returnReason: string; createdAt: string; docs: string[] };
type RouteRow = { id: string; name: string; loadingPoint: string; unloadingPoint: string; distance: number; manual: boolean; active: boolean };
type MonthlyRow = { id: string; month: string; mileage: number; fuel: number; fuelPrice: number; wages: number; leasing: number; repairs: number; insurance: number; tyres: number; consumables: number; idleHours: number; idlePrice: number };
type Settings = { mrp: number; oneDayMrp: number; overnightDayMrp: number; overnightNightMrp: number; company: string; vehicle: string };

type BuilderTab = { id: string; label: string; systemTarget?: SystemTab; visible: boolean; archived: boolean; order: number };
type BuilderField = { id: string; sectionId: string; label: string; key: string; type: FieldType; required: boolean; visible: boolean; archived: boolean; order: number; options: string[] };
type BuilderSection = { id: string; tabId: string; title: string; description: string; type: SectionType; visible: boolean; archived: boolean; order: number };
type BuilderAction = { id: string; tabId: string; label: string; type: ActionType; visible: boolean; archived: boolean; order: number; confirmation: string };
type BuilderRole = { id: string; name: string; active: boolean; permissions: string[] };
type CustomRecord = { id: string; sectionId: string; values: Record<string, string | number | boolean>; createdAt: string; updatedAt: string; archived: boolean };
type AuditRow = { id: string; at: string; actor: string; action: string; entity: string; entityId: string; details: string };
type BuilderState = { tabs: BuilderTab[]; sections: BuilderSection[]; fields: BuilderField[]; actions: BuilderAction[]; roles: BuilderRole[]; records: CustomRecord[] };
type DataState = { users: UserRow[]; places: PlaceRow[]; tariffs: TariffRow[]; templates: TemplateRow[]; requests: RequestRow[]; routes: RouteRow[]; monthly: MonthlyRow[]; settings: Settings; builder: BuilderState; audit: AuditRow[] };
type ModalState = { kind: ModalKind; id?: string; parentId?: string };

const STORAGE_KEY = "gazel-logistics-web-v2";
const LEGACY_STORAGE_KEY = "gazel-logistics-web-v1";
const today = new Date().toISOString().slice(0, 10);
const nowLocal = () => new Date(Date.now() - new Date().getTimezoneOffset() * 60000).toISOString().slice(0, 16);
const uid = (prefix: string) => `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2)}`;
const systemTabs: Array<{ id: SystemTab; label: string }> = [
  { id: "dashboard", label: "Главная" },
  { id: "requests", label: "Заявки" },
  { id: "approval", label: "Согласование" },
  { id: "routes", label: "Маршруты" },
  { id: "documents", label: "Бланки и документы" },
  { id: "reports", label: "Месячный отчёт" },
  { id: "directories", label: "Справочники" },
  { id: "admin", label: "Администрирование" },
];
const defaultBuilder: BuilderState = {
  tabs: systemTabs.map((tab, order) => ({ id: tab.id, label: tab.label, systemTarget: tab.id, visible: true, archived: false, order })),
  sections: [],
  fields: [],
  actions: [],
  roles: [
    { id: "role-admin", name: "Администратор", active: true, permissions: ["view", "create", "edit", "delete", "approve", "return", "configure", "export"] },
    { id: "role-dispatcher", name: "Диспетчер", active: true, permissions: ["view", "create", "edit", "send"] },
    { id: "role-driver", name: "Водитель", active: true, permissions: ["view-own", "sign"] },
  ],
  records: [],
};
const initialData: DataState = {
  settings: { mrp: 3932, oneDayMrp: 1, overnightDayMrp: 3, overnightNightMrp: 4, company: "ТОО AA Mining", vehicle: "ГАЗ A22R33" },
  users: [
    { id: "u-admin", name: "Администратор", login: "admin", role: "Администратор", active: true, terminationDate: "", archived: false },
    { id: "u-driver-1", name: "Водитель 1", login: "driver1", role: "Водитель", active: true, terminationDate: "", archived: false },
    { id: "u-dispatcher", name: "Диспетчер", login: "dispatcher", role: "Диспетчер", active: true, terminationDate: "", archived: false },
  ],
  places: [
    { id: "p-astana", name: "Астана", category: "Город республиканского значения", manual: false, active: true },
    { id: "p-step", name: "Степногорск", category: "Город областного значения", manual: false, active: true },
    { id: "p-zhol", name: "Жолымбет", category: "Населённый пункт", manual: true, active: true },
  ],
  tariffs: [
    { id: "t-one", name: "Однодневная поездка", category: "Все категории", dayRate: 0, nightRate: 0, oneDayRate: 1, active: true },
    { id: "t-republic", name: "Командировка с ночёвкой", category: "Город республиканского значения", dayRate: 3, nightRate: 4, oneDayRate: 1, active: true },
    { id: "t-region", name: "Командировка с ночёвкой", category: "Город областного значения", dayRate: 3, nightRate: 4, oneDayRate: 1, active: true },
  ],
  templates: [
    { id: "tpl-1", name: "Служебная записка", type: "Служебная записка", version: "1.0", effectiveFrom: today, active: true, fileName: "", mimeType: "", dataUrl: "", usedCount: 0 },
    { id: "tpl-2", name: "Расчёт командировочных", type: "Расчёт", version: "1.0", effectiveFrom: today, active: true, fileName: "", mimeType: "", dataUrl: "", usedCount: 0 },
  ],
  requests: [
    { id: "r-1", number: "ЗГ-0001", author: "Диспетчер", route: "Степногорск → Астана → Степногорск", purpose: "Доставка документов", departureAt: nowLocal(), returnAt: nowLocal(), driver: "Водитель 1", vehicle: "ГАЗ A22R33", status: "На согласовании", returnReason: "", createdAt: new Date().toLocaleString("ru-RU"), docs: [] },
  ],
  routes: [{ id: "route-1", name: "Степногорск — Астана", loadingPoint: "Степногорск", unloadingPoint: "Астана", distance: 390, manual: false, active: true }],
  monthly: [{ id: "m-current", month: new Date().toISOString().slice(0, 7), mileage: 0, fuel: 0, fuelPrice: 240, wages: 840000, leasing: 0, repairs: 0, insurance: 0, tyres: 0, consumables: 0, idleHours: 0, idlePrice: 0 }],
  builder: defaultBuilder,
  audit: [],
};

function formatNumber(value: number) { return new Intl.NumberFormat("ru-RU", { maximumFractionDigits: 6 }).format(Number.isFinite(value) ? value : 0); }
function money(value: number) { return `${new Intl.NumberFormat("ru-RU", { maximumFractionDigits: 2 }).format(Number.isFinite(value) ? value : 0)} ₸`; }
function n(value: FormDataEntryValue | null) { return Number(String(value ?? "").replace(",", ".")) || 0; }
function s(value: FormDataEntryValue | null) { return String(value ?? "").trim(); }
function sorted<T extends { order: number }>(rows: T[]) { return [...rows].sort((a, b) => a.order - b.order); }
function mergeStored(value: Partial<DataState>): DataState {
  const storedBuilder = value.builder;
  return {
    ...initialData,
    ...value,
    settings: { ...initialData.settings, ...(value.settings || {}) },
    builder: {
      tabs: storedBuilder?.tabs?.length ? storedBuilder.tabs : defaultBuilder.tabs,
      sections: storedBuilder?.sections || [],
      fields: storedBuilder?.fields || [],
      actions: storedBuilder?.actions || [],
      roles: storedBuilder?.roles?.length ? storedBuilder.roles : defaultBuilder.roles,
      records: storedBuilder?.records || [],
    },
    audit: value.audit || [],
  };
}

export default function LogisticsWorkspace() {
  const [authenticated, setAuthenticated] = useState(false);
  const [loginError, setLoginError] = useState("");
  const [tab, setTab] = useState<string>("dashboard");
  const [data, setData] = useState<DataState>(initialData);
  const [modal, setModal] = useState<ModalState>({ kind: null });
  const [notice, setNotice] = useState("");

  useEffect(() => {
    setAuthenticated(sessionStorage.getItem("gazel-auth") === "1");
    try {
      const stored = localStorage.getItem(STORAGE_KEY) || localStorage.getItem(LEGACY_STORAGE_KEY);
      if (stored) setData(mergeStored(JSON.parse(stored) as Partial<DataState>));
    } catch { /* defaults */ }
  }, []);
  useEffect(() => { localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); }, [data]);
  useEffect(() => { if (!notice) return; const timer = setTimeout(() => setNotice(""), 3500); return () => clearTimeout(timer); }, [notice]);

  const pending = data.requests.filter((item) => item.status === "На согласовании");
  const activeUsers = data.users.filter((item) => item.active && !item.archived);
  const report = data.monthly[0];
  const monthlyTotal = report ? report.fuel * report.fuelPrice + report.wages + report.leasing + report.repairs + report.insurance + report.tyres + report.consumables + report.idleHours * report.idlePrice : 0;
  const visibleTabs = useMemo(() => sorted(data.builder.tabs.filter((item) => item.visible && !item.archived)), [data.builder.tabs]);
  const currentTab = data.builder.tabs.find((item) => item.id === tab);

  function login(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    if (s(form.get("login")) === "admin" && s(form.get("password")) === "admin12345") {
      sessionStorage.setItem("gazel-auth", "1"); setAuthenticated(true); setLoginError("");
    } else setLoginError("Неверный логин или пароль");
  }
  function logout() { sessionStorage.removeItem("gazel-auth"); setAuthenticated(false); }
  function update<K extends keyof DataState>(key: K, value: DataState[K]) { setData((current) => ({ ...current, [key]: value })); }
  function audit(action: string, entity: string, entityId: string, details: string) {
    setData((current) => ({ ...current, audit: [{ id: uid("audit"), at: new Date().toLocaleString("ru-RU"), actor: "Администратор", action, entity, entityId, details }, ...current.audit].slice(0, 500) }));
  }
  function updateBuilder(next: BuilderState, action: string, entity: string, entityId: string, details: string) {
    setData((current) => ({ ...current, builder: next, audit: [{ id: uid("audit"), at: new Date().toLocaleString("ru-RU"), actor: "Администратор", action, entity, entityId, details }, ...current.audit].slice(0, 500) }));
  }
  function removeRequest(id: string) { if (confirm("Удалить заявку?")) { update("requests", data.requests.filter((row) => row.id !== id)); audit("Удаление", "Заявка", id, "Заявка удалена администратором"); } }
  function sendForApproval(id: string) { update("requests", data.requests.map((row) => row.id === id ? { ...row, status: "На согласовании", returnReason: "" } : row)); setNotice("Заявка отправлена на согласование"); }
  function approve(id: string) {
    const docs = ["Служебная записка", "Расчёт командировочных", "Заявление водителя", "Согласие на удержание", "Счёт на оплату", "Путевой лист", "Контрольный лист выпуска"];
    setData((current) => ({ ...current, requests: current.requests.map((row) => row.id === id ? { ...row, status: "Согласована", docs } : row), templates: current.templates.map((tpl) => ({ ...tpl, usedCount: tpl.usedCount + (tpl.active ? 1 : 0) })) }));
    setNotice("Заявка согласована. Пакет документов сформирован");
  }
  function returnToAuthor(id: string) { const reason = prompt("Укажите причину возврата автору:"); if (!reason?.trim()) return; update("requests", data.requests.map((row) => row.id === id ? { ...row, status: "Возвращена", returnReason: reason.trim() } : row)); setNotice("Заявка возвращена автору"); }
  function printPackage(row: RequestRow) {
    const win = window.open("", "_blank", "width=1000,height=800"); if (!win) return;
    const docs = row.docs.length ? row.docs : ["Черновик пакета документов"];
    win.document.write(`<!doctype html><html lang="ru"><head><meta charset="utf-8"><title>${row.number}</title><style>body{font-family:Arial,sans-serif;margin:36px;color:#111}section{page-break-after:always;min-height:900px}h1{font-size:22px}dl{display:grid;grid-template-columns:220px 1fr;gap:10px}dt{font-weight:700}.sign{margin-top:90px;display:flex;justify-content:space-between}</style></head><body>${docs.map((doc) => `<section><h1>${doc}</h1><dl><dt>Заявка</dt><dd>${row.number}</dd><dt>Автор</dt><dd>${row.author}</dd><dt>Маршрут</dt><dd>${row.route}</dd><dt>Цель</dt><dd>${row.purpose}</dd><dt>Водитель</dt><dd>${row.driver}</dd><dt>Автомобиль</dt><dd>${row.vehicle}</dd><dt>Период</dt><dd>${row.departureAt} — ${row.returnAt}</dd></dl><div class="sign"><span>Подпись: ____________</span><span>Дата: ____________</span></div></section>`).join("")}</body></html>`);
    win.document.close(); win.focus(); setTimeout(() => win.print(), 300);
  }
  function archiveUser(row: UserRow) {
    const linked = data.requests.some((request) => request.author === row.name || request.driver === row.name);
    if (linked) { const date = prompt("Укажите дату увольнения (ГГГГ-ММ-ДД):", row.terminationDate || today) || today; update("users", data.users.map((user) => user.id === row.id ? { ...user, active: false, terminationDate: date, archived: true } : user)); setNotice("Пользователь деактивирован, история сохранена"); }
    else if (confirm("У пользователя нет связанной истории. Удалить окончательно?")) update("users", data.users.filter((user) => user.id !== row.id));
  }
  function exportData() { const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" }); const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = `gazel-logistics-${today}.json`; a.click(); URL.revokeObjectURL(a.href); }
  function importData(file: File) { const reader = new FileReader(); reader.onload = () => { try { setData(mergeStored(JSON.parse(String(reader.result)) as Partial<DataState>)); setNotice("Резервная копия загружена"); } catch { alert("Файл не является корректной резервной копией"); } }; reader.readAsText(file); }

  if (!authenticated) return <LoginScreen onSubmit={login} error={loginError} />;

  return (
    <main className={styles.app}>
      <header className={styles.header}>
        <div><div className={styles.eyebrow}>AA Mining · веб-конструктор</div><h1>Логистика Газели</h1><p>Структура, формы, поля и права настраиваются администратором без изменения кода</p></div>
        <div className={styles.headerActions}><span className={styles.adminBadge}>Администратор · полный доступ</span><button className={styles.secondary} onClick={() => setTab("admin")}>Конструктор</button><button className={styles.secondary} onClick={logout}>Выйти</button></div>
      </header>
      <nav className={styles.tabs}>{visibleTabs.map((item) => <button key={item.id} className={tab === item.id ? styles.activeTab : ""} onClick={() => setTab(item.id)}>{item.label}{item.systemTarget === "approval" && pending.length > 0 ? <b>{pending.length}</b> : null}</button>)}</nav>
      {notice ? <div className={styles.notice}>{notice}</div> : null}

      {currentTab?.systemTarget === "dashboard" && <Dashboard data={data} pending={pending.length} activeUsers={activeUsers.length} monthlyTotal={monthlyTotal} setTab={setTab} />}
      {currentTab?.systemTarget === "requests" && <Requests data={data} open={setModal} remove={removeRequest} send={sendForApproval} print={printPackage} />}
      {currentTab?.systemTarget === "approval" && <Approval rows={pending} approve={approve} returnToAuthor={returnToAuthor} open={setModal} />}
      {currentTab?.systemTarget === "routes" && <Routes rows={data.routes} open={setModal} updateRows={(rows) => update("routes", rows)} />}
      {currentTab?.systemTarget === "documents" && <Documents templates={data.templates} requests={data.requests} open={setModal} print={printPackage} updateTemplates={(rows) => update("templates", rows)} />}
      {currentTab?.systemTarget === "reports" && <MonthlyReport row={report} total={monthlyTotal} open={setModal} />}
      {currentTab?.systemTarget === "directories" && <Directories data={data} open={setModal} updateData={update} />}
      {currentTab?.systemTarget === "admin" && <Admin data={data} open={setModal} archiveUser={archiveUser} updateUsers={(rows) => update("users", rows)} exportData={exportData} importData={importData} updateBuilder={updateBuilder} />}
      {currentTab && !currentTab.systemTarget && <CustomTabPage tab={currentTab} data={data} open={setModal} updateBuilder={updateBuilder} exportData={exportData} notice={setNotice} />}
      {!currentTab && <Empty text="Раздел скрыт или удалён. Откройте «Конструктор» в правом верхнем углу и восстановите его." />}

      {modal.kind && <EditorModal modal={modal} data={data} close={() => setModal({ kind: null })} update={update} updateBuilder={updateBuilder} notice={setNotice} />}
    </main>
  );
}

function LoginScreen({ onSubmit, error }: { onSubmit: (e: FormEvent<HTMLFormElement>) => void; error: string }) {
  return <main className={styles.loginPage}><form className={styles.loginCard} onSubmit={onSubmit}><div className={styles.logo}>AA</div><h1>Логистика Газели</h1><p>Веб-система и конструктор администратора</p><label>Логин<input name="login" defaultValue="admin" autoComplete="username" /></label><label>Пароль<input name="password" type="password" defaultValue="admin12345" autoComplete="current-password" /></label>{error ? <div className={styles.error}>{error}</div> : null}<button className={styles.primary}>Войти</button></form></main>;
}

function Dashboard({ data, pending, activeUsers, monthlyTotal, setTab }: { data: DataState; pending: number; activeUsers: number; monthlyTotal: number; setTab: (tab: string) => void }) {
  const approved = data.requests.filter((r) => r.status === "Согласована").length;
  return <section className={styles.page}><div className={styles.cards}><Metric label="Всего заявок" value={String(data.requests.length)} /><Metric label="На согласовании" value={String(pending)} tone={pending ? "warning" : "normal"} /><Metric label="Согласовано" value={String(approved)} /><Metric label="Расходы месяца" value={money(monthlyTotal)} /><Metric label="Активные пользователи" value={String(activeUsers)} /></div><div className={styles.grid2}><Panel title="Быстрые действия"><div className={styles.actionGrid}><button onClick={() => setTab("requests")}>Создать заявку</button><button onClick={() => setTab("approval")}>Открыть согласование</button><button onClick={() => setTab("documents")}>Официальные бланки</button><button onClick={() => setTab("admin")}>Конструктор системы</button></div></Panel><Panel title="Контроль настроек"><Status label="МРП" value={money(data.settings.mrp)} /><Status label="Активные тарифы" value={String(data.tariffs.filter((x) => x.active).length)} /><Status label="Активные бланки" value={String(data.templates.filter((x) => x.active).length)} /><Status label="Настраиваемые вкладки" value={String(data.builder.tabs.length)} /></Panel></div></section>;
}

function Requests({ data, open, remove, send, print }: { data: DataState; open: (m: ModalState) => void; remove: (id: string) => void; send: (id: string) => void; print: (r: RequestRow) => void }) {
  return <section className={styles.page}><PageHead title="Заявки" text="Создание, редактирование, отправка на согласование и печать пакета." action="Создать заявку" onAction={() => open({ kind: "request" })} /><Table headers={["№", "Автор", "Маршрут", "Период", "Водитель", "Статус", "Действия"]}>{data.requests.map((row) => <tr key={row.id}><td><strong>{row.number}</strong></td><td>{row.author}</td><td>{row.route}<small>{row.purpose}</small></td><td>{row.departureAt.replace("T", " ")}<small>до {row.returnAt.replace("T", " ")}</small></td><td>{row.driver}<small>{row.vehicle}</small></td><td><Badge status={row.status} />{row.returnReason ? <small className={styles.dangerText}>{row.returnReason}</small> : null}</td><td><Actions><button onClick={() => open({ kind: "request", id: row.id })}>Изменить</button>{row.status === "Черновик" || row.status === "Возвращена" ? <button onClick={() => send(row.id)}>Отправить</button> : null}{row.status === "Согласована" ? <button onClick={() => print(row)}>Печать / PDF</button> : null}<button className={styles.dangerButton} onClick={() => remove(row.id)}>Удалить</button></Actions></td></tr>)}</Table></section>;
}
function Approval({ rows, approve, returnToAuthor, open }: { rows: RequestRow[]; approve: (id: string) => void; returnToAuthor: (id: string) => void; open: (m: ModalState) => void }) {
  return <section className={styles.page}><PageHead title="Согласование" text="Администратор может согласовать, изменить данные или вернуть заявку автору." />{rows.length === 0 ? <Empty text="Нет заявок, ожидающих согласования." /> : <Table headers={["№", "Маршрут", "Автор", "Назначение", "Действия"]}>{rows.map((row) => <tr key={row.id}><td><strong>{row.number}</strong><small>{row.createdAt}</small></td><td>{row.route}<small>{row.departureAt.replace("T", " ")} — {row.returnAt.replace("T", " ")}</small></td><td>{row.author}</td><td>{row.driver}<small>{row.vehicle}</small></td><td><Actions><button onClick={() => open({ kind: "request", id: row.id })}>Изменить</button><button className={styles.approveButton} onClick={() => approve(row.id)}>Согласовать и оформить</button><button className={styles.dangerButton} onClick={() => returnToAuthor(row.id)}>Вернуть автору</button></Actions></td></tr>)}</Table>}</section>;
}
function Routes({ rows, open, updateRows }: { rows: RouteRow[]; open: (m: ModalState) => void; updateRows: (r: RouteRow[]) => void }) {
  return <section className={styles.page}><PageHead title="Маршруты и пункты" text="Пункты загрузки и выгрузки можно выбирать из справочника либо вводить вручную." action="Добавить маршрут" onAction={() => open({ kind: "route" })} /><Table headers={["Маршрут", "Загрузка", "Выгрузка", "Расстояние", "Ручной ввод", "Статус", "Действия"]}>{rows.map((row) => <tr key={row.id}><td><strong>{row.name}</strong></td><td>{row.loadingPoint}</td><td>{row.unloadingPoint}</td><td>{formatNumber(row.distance)} км</td><td>{row.manual ? "Да" : "Нет"}</td><td>{row.active ? "Активен" : "Отключён"}</td><td><Actions><button onClick={() => open({ kind: "route", id: row.id })}>Изменить</button><button onClick={() => updateRows(rows.map((x) => x.id === row.id ? { ...x, active: !x.active } : x))}>{row.active ? "Деактивировать" : "Восстановить"}</button><button className={styles.dangerButton} onClick={() => confirm("Удалить маршрут?") && updateRows(rows.filter((x) => x.id !== row.id))}>Удалить</button></Actions></td></tr>)}</Table></section>;
}
function Documents({ templates, requests, open, print, updateTemplates }: { templates: TemplateRow[]; requests: RequestRow[]; open: (m: ModalState) => void; print: (r: RequestRow) => void; updateTemplates: (rows: TemplateRow[]) => void }) {
  const generated = requests.filter((r) => r.docs.length > 0);
  return <section className={styles.page}><PageHead title="Официальные бланки" text="Загрузка собственных DOCX/PDF, просмотр, версии и история использования." action="Загрузить бланк" onAction={() => open({ kind: "template" })} /><Table headers={["Название", "Тип", "Версия", "Действует с", "Файл", "Использован", "Статус", "Действия"]}>{templates.map((row) => <tr key={row.id}><td><strong>{row.name}</strong></td><td>{row.type}</td><td>{row.version}</td><td>{row.effectiveFrom}</td><td>{row.fileName || "Не загружен"}</td><td>{row.usedCount}</td><td>{row.active ? "Активен" : "Архив"}</td><td><Actions><button onClick={() => open({ kind: "preview", id: row.id })}>Просмотр</button><button onClick={() => open({ kind: "template", id: row.id })}>Изменить</button><button onClick={() => updateTemplates(templates.map((x) => x.id === row.id ? { ...x, active: !x.active } : x))}>{row.active ? "В архив" : "Активировать"}</button>{row.usedCount === 0 ? <button className={styles.dangerButton} onClick={() => confirm("Удалить неиспользованный шаблон?") && updateTemplates(templates.filter((x) => x.id !== row.id))}>Удалить</button> : null}</Actions></td></tr>)}</Table><h2 className={styles.sectionTitle}>Сформированные пакеты</h2>{generated.length === 0 ? <Empty text="После согласования заявки здесь появится пакет документов." /> : <Table headers={["Заявка", "Маршрут", "Документы", "Действие"]}>{generated.map((row) => <tr key={row.id}><td>{row.number}</td><td>{row.route}</td><td>{row.docs.join(", ")}</td><td><button onClick={() => print(row)}>Открыть для печати / PDF</button></td></tr>)}</Table>}</section>;
}
function MonthlyReport({ row, total, open }: { row: MonthlyRow | undefined; total: number; open: (m: ModalState) => void }) {
  if (!row) return <Empty text="Нет данных месячного отчёта." />;
  const fuelCost = row.fuel * row.fuelPrice; const idleCost = row.idleHours * row.idlePrice;
  return <section className={styles.page}><PageHead title="Месячный отчёт" text="Все цены доступны для редактирования администратору." action="Редактировать показатели и цены" onAction={() => open({ kind: "monthly", id: row.id })} /><div className={styles.cards}><Metric label="Пробег" value={`${formatNumber(row.mileage)} км`} /><Metric label="Топливо" value={`${formatNumber(row.fuel)} л`} /><Metric label="Стоимость топлива" value={money(fuelCost)} /><Metric label="Простой" value={`${formatNumber(row.idleHours)} ч / ${money(idleCost)}`} /><Metric label="Итого расходов" value={money(total)} /></div><Table headers={["Статья", "Количество / база", "Цена", "Сумма"]}><tr><td>Топливо</td><td>{formatNumber(row.fuel)} л</td><td>{money(row.fuelPrice)} / л</td><td>{money(fuelCost)}</td></tr><tr><td>Заработная плата водителей</td><td>2 водителя, график 15/15</td><td>Редактируется</td><td>{money(row.wages)}</td></tr><tr><td>Лизинг</td><td>Месяц</td><td>Редактируется</td><td>{money(row.leasing)}</td></tr><tr><td>Ремонты</td><td>Факт</td><td>Редактируется</td><td>{money(row.repairs)}</td></tr><tr><td>Страхование и техосмотр</td><td>Начисление месяца</td><td>Редактируется</td><td>{money(row.insurance)}</td></tr><tr><td>Шины</td><td>Начисление / факт</td><td>Редактируется</td><td>{money(row.tyres)}</td></tr><tr><td>Расходные материалы</td><td>Факт</td><td>Редактируется</td><td>{money(row.consumables)}</td></tr><tr><td>Простой</td><td>{formatNumber(row.idleHours)} ч</td><td>{money(row.idlePrice)} / ч</td><td>{money(idleCost)}</td></tr><tr className={styles.totalRow}><td colSpan={3}>ИТОГО</td><td>{money(total)}</td></tr></Table></section>;
}
function Directories({ data, open, updateData }: { data: DataState; open: (m: ModalState) => void; updateData: <K extends keyof DataState>(k: K, v: DataState[K]) => void }) {
  return <section className={styles.page}><div className={styles.grid2}><Panel title="Населённые пункты"><button className={styles.primarySmall} onClick={() => open({ kind: "place" })}>Добавить пункт</button><div className={styles.list}>{data.places.map((row) => <div key={row.id}><span><strong>{row.name}</strong><small>{row.category}{row.manual ? " · добавлен вручную" : ""}</small></span><Actions><button onClick={() => open({ kind: "place", id: row.id })}>Изменить</button><button onClick={() => updateData("places", data.places.map((x) => x.id === row.id ? { ...x, active: !x.active } : x))}>{row.active ? "Отключить" : "Включить"}</button></Actions></div>)}</div></Panel><Panel title="Тарифная сетка"><button className={styles.primarySmall} onClick={() => open({ kind: "tariff" })}>Добавить тариф</button><div className={styles.list}>{data.tariffs.map((row) => <div key={row.id}><span><strong>{row.name}</strong><small>{row.category} · день {formatNumber(row.dayRate)} МРП · ночь {formatNumber(row.nightRate)} МРП</small></span><Actions><button onClick={() => open({ kind: "tariff", id: row.id })}>Изменить</button><button onClick={() => updateData("tariffs", data.tariffs.map((x) => x.id === row.id ? { ...x, active: !x.active } : x))}>{row.active ? "Отключить" : "Включить"}</button></Actions></div>)}</div></Panel></div><Panel title="Начальные настройки"><div className={styles.settingsGrid}><Status label="Компания" value={data.settings.company} /><Status label="Автомобиль" value={data.settings.vehicle} /><Status label="МРП" value={money(data.settings.mrp)} /><Status label="Однодневная поездка" value={`${formatNumber(data.settings.oneDayMrp)} МРП`} /><Status label="День с ночёвкой" value={`${formatNumber(data.settings.overnightDayMrp)} МРП`} /><Status label="Ночь" value={`${formatNumber(data.settings.overnightNightMrp)} МРП`} /></div><button className={styles.primarySmall} onClick={() => open({ kind: "settings" })}>Изменить начальные настройки</button></Panel></section>;
}
function Admin({ data, open, archiveUser, updateUsers, exportData, importData, updateBuilder }: { data: DataState; open: (m: ModalState) => void; archiveUser: (u: UserRow) => void; updateUsers: (u: UserRow[]) => void; exportData: () => void; importData: (f: File) => void; updateBuilder: (next: BuilderState, action: string, entity: string, entityId: string, details: string) => void }) {
  const [mode, setMode] = useState<"constructor" | "users" | "roles" | "history" | "backup">("constructor");
  const [selectedTab, setSelectedTab] = useState(data.builder.tabs[0]?.id || "dashboard");
  const [selectedSection, setSelectedSection] = useState("");
  const tabSections = sorted(data.builder.sections.filter((x) => x.tabId === selectedTab));
  const sectionFields = sorted(data.builder.fields.filter((x) => x.sectionId === selectedSection));
  const tabActions = sorted(data.builder.actions.filter((x) => x.tabId === selectedTab));
  function move<T extends { id: string; order: number }>(rows: T[], id: string, direction: -1 | 1) { const ordered = sorted(rows); const index = ordered.findIndex((x) => x.id === id); const swap = index + direction; if (index < 0 || swap < 0 || swap >= ordered.length) return rows; const a = ordered[index]; const b = ordered[swap]; return rows.map((x) => x.id === a.id ? { ...x, order: b.order } : x.id === b.id ? { ...x, order: a.order } : x); }
  function removeTab(id: string) { if (!confirm("Удалить вкладку из сайта? Она попадёт в архив и сможет быть восстановлена.")) return; updateBuilder({ ...data.builder, tabs: data.builder.tabs.map((x) => x.id === id ? { ...x, archived: true, visible: false } : x) }, "Удаление в архив", "Вкладка", id, "Вкладка удалена из меню с сохранением конфигурации"); }
  function hardDeleteTab(id: string) { if (!confirm("Удалить вкладку, её разделы, поля и записи окончательно?")) return; const sectionIds = data.builder.sections.filter((x) => x.tabId === id).map((x) => x.id); updateBuilder({ ...data.builder, tabs: data.builder.tabs.filter((x) => x.id !== id), sections: data.builder.sections.filter((x) => x.tabId !== id), fields: data.builder.fields.filter((x) => !sectionIds.includes(x.sectionId)), actions: data.builder.actions.filter((x) => x.tabId !== id), records: data.builder.records.filter((x) => !sectionIds.includes(x.sectionId)) }, "Окончательное удаление", "Вкладка", id, "Удалена вкладка со связанными объектами"); }
  return <section className={styles.page}><PageHead title="Администрирование" text="Полный конструктор структуры сайта, форм, полей, действий, ролей и истории." /><div className={styles.adminModes}>{[["constructor","Конструктор системы"],["users","Пользователи"],["roles","Роли и права"],["history","История изменений"],["backup","Резервная копия"]].map(([id,label]) => <button key={id} className={mode === id ? styles.activeMode : ""} onClick={() => setMode(id as typeof mode)}>{label}</button>)}</div>
  {mode === "constructor" && <><div className={styles.constructorIntro}><div><strong>Сайт управляется из конструктора</strong><p>Создавайте и удаляйте вкладки, добавляйте разделы, поля и кнопки. Системные вкладки также можно переименовать, скрыть, переместить или отправить в архив.</p></div><Actions><button className={styles.primary} onClick={() => open({ kind: "builder-tab" })}>Добавить вкладку</button><button onClick={() => updateBuilder({ ...data.builder, tabs: defaultBuilder.tabs }, "Восстановление", "Система", "tabs", "Восстановлены стандартные вкладки")}>Восстановить стандартные вкладки</button></Actions></div><div className={styles.builderLayout}><aside className={styles.builderSidebar}><h3>Вкладки сайта</h3>{sorted(data.builder.tabs).map((row) => <div key={row.id} className={`${styles.builderItem} ${selectedTab === row.id ? styles.builderSelected : ""} ${row.archived ? styles.builderArchived : ""}`}><button className={styles.builderSelect} onClick={() => { setSelectedTab(row.id); setSelectedSection(""); }}>{row.label}<small>{row.systemTarget ? "системная" : "пользовательская"}{row.archived ? " · архив" : row.visible ? " · видна" : " · скрыта"}</small></button><Actions><button onClick={() => open({ kind: "builder-tab", id: row.id })}>✎</button><button onClick={() => updateBuilder({ ...data.builder, tabs: move(data.builder.tabs, row.id, -1) }, "Перемещение", "Вкладка", row.id, "Вкладка перемещена выше")}>↑</button><button onClick={() => updateBuilder({ ...data.builder, tabs: move(data.builder.tabs, row.id, 1) }, "Перемещение", "Вкладка", row.id, "Вкладка перемещена ниже")}>↓</button>{row.archived ? <><button onClick={() => updateBuilder({ ...data.builder, tabs: data.builder.tabs.map((x) => x.id === row.id ? { ...x, archived: false, visible: true } : x) }, "Восстановление", "Вкладка", row.id, "Вкладка восстановлена")}>↺</button><button className={styles.dangerButton} onClick={() => hardDeleteTab(row.id)}>×</button></> : <button className={styles.dangerButton} onClick={() => removeTab(row.id)}>×</button>}</Actions></div>)}</aside><div className={styles.builderCanvas}><div className={styles.builderCanvasHead}><div><h3>{data.builder.tabs.find((x) => x.id === selectedTab)?.label || "Выберите вкладку"}</h3><p>Разделы выбранной вкладки</p></div><Actions><button className={styles.primarySmall} onClick={() => open({ kind: "builder-section", parentId: selectedTab })}>Добавить раздел</button><button onClick={() => open({ kind: "builder-action", parentId: selectedTab })}>Добавить кнопку</button></Actions></div>{tabSections.length === 0 ? <Empty text="В этой вкладке нет настраиваемых разделов. Добавьте форму, таблицу или информационный блок." /> : <div className={styles.sectionCards}>{tabSections.map((section) => <div key={section.id} className={`${styles.sectionCard} ${section.archived ? styles.builderArchived : ""}`}><button className={styles.sectionSelect} onClick={() => setSelectedSection(section.id)}><strong>{section.title}</strong><small>{section.type} · {section.visible ? "виден" : "скрыт"} · полей {data.builder.fields.filter((x) => x.sectionId === section.id && !x.archived).length}</small></button><Actions><button onClick={() => open({ kind: "builder-section", id: section.id, parentId: selectedTab })}>Изменить</button><button onClick={() => setSelectedSection(section.id)}>Поля</button><button className={styles.dangerButton} onClick={() => updateBuilder({ ...data.builder, sections: data.builder.sections.map((x) => x.id === section.id ? { ...x, archived: !x.archived, visible: x.archived } : x) }, section.archived ? "Восстановление" : "Удаление в архив", "Раздел", section.id, section.archived ? "Раздел восстановлен" : "Раздел отправлен в архив")}>{section.archived ? "Восстановить" : "Удалить"}</button></Actions></div>)}</div>}<div className={styles.builderSubGrid}><Panel title="Поля выбранного раздела"><button className={styles.primarySmall} disabled={!selectedSection} onClick={() => open({ kind: "builder-field", parentId: selectedSection })}>Добавить поле</button>{!selectedSection ? <p>Выберите раздел выше.</p> : sectionFields.length === 0 ? <Empty text="Поля ещё не добавлены." /> : <div className={styles.list}>{sectionFields.map((field) => <div key={field.id}><span><strong>{field.label}</strong><small>{field.type} · ключ {field.key} · {field.required ? "обязательное" : "необязательное"}{field.archived ? " · архив" : ""}</small></span><Actions><button onClick={() => open({ kind: "builder-field", id: field.id, parentId: selectedSection })}>Изменить</button><button className={styles.dangerButton} onClick={() => updateBuilder({ ...data.builder, fields: data.builder.fields.map((x) => x.id === field.id ? { ...x, archived: !x.archived, visible: x.archived } : x) }, field.archived ? "Восстановление" : "Удаление в архив", "Поле", field.id, field.archived ? "Поле восстановлено" : "Поле удалено из формы")}>{field.archived ? "Восстановить" : "Удалить"}</button></Actions></div>)}</div>}</Panel><Panel title="Кнопки выбранной вкладки">{tabActions.length === 0 ? <Empty text="Дополнительные кнопки не настроены." /> : <div className={styles.list}>{tabActions.map((action) => <div key={action.id}><span><strong>{action.label}</strong><small>{action.type} · {action.visible ? "видна" : "скрыта"}{action.archived ? " · архив" : ""}</small></span><Actions><button onClick={() => open({ kind: "builder-action", id: action.id, parentId: selectedTab })}>Изменить</button><button className={styles.dangerButton} onClick={() => updateBuilder({ ...data.builder, actions: data.builder.actions.map((x) => x.id === action.id ? { ...x, archived: !x.archived, visible: x.archived } : x) }, action.archived ? "Восстановление" : "Удаление в архив", "Кнопка", action.id, action.archived ? "Кнопка восстановлена" : "Кнопка удалена")}>{action.archived ? "Восстановить" : "Удалить"}</button></Actions></div>)}</div>}</Panel></div></div></div></>}
  {mode === "users" && <><PageHead title="Пользователи" text="Деактивация и увольнение не удаляют прежнюю историю." action="Добавить пользователя" onAction={() => open({ kind: "user" })} /><Table headers={["ФИО", "Логин", "Роль", "Статус", "Дата увольнения", "Действия"]}>{data.users.map((row) => <tr key={row.id}><td><strong>{row.name}</strong></td><td>{row.login}</td><td>{row.role}</td><td>{row.active ? "Активен" : row.archived ? "Архив / уволен" : "Деактивирован"}</td><td>{row.terminationDate || "—"}</td><td><Actions><button onClick={() => open({ kind: "user", id: row.id })}>Изменить</button>{!row.active ? <button onClick={() => updateUsers(data.users.map((x) => x.id === row.id ? { ...x, active: true, archived: false, terminationDate: "" } : x))}>Восстановить</button> : <button className={styles.dangerButton} onClick={() => archiveUser(row)}>Удалить / деактивировать</button>}</Actions></td></tr>)}</Table></>}
  {mode === "roles" && <><PageHead title="Роли и права" text="Администратор может создавать собственные роли и наборы разрешений." action="Добавить роль" onAction={() => open({ kind: "builder-role" })} /><Table headers={["Роль", "Статус", "Разрешения", "Действия"]}>{data.builder.roles.map((role) => <tr key={role.id}><td><strong>{role.name}</strong></td><td>{role.active ? "Активна" : "Отключена"}</td><td>{role.permissions.join(", ") || "Нет разрешений"}</td><td><Actions><button onClick={() => open({ kind: "builder-role", id: role.id })}>Изменить</button><button onClick={() => updateBuilder({ ...data.builder, roles: data.builder.roles.map((x) => x.id === role.id ? { ...x, active: !x.active } : x) }, "Изменение статуса", "Роль", role.id, role.active ? "Роль отключена" : "Роль включена")}>{role.active ? "Отключить" : "Включить"}</button><button className={styles.dangerButton} onClick={() => confirm("Удалить роль?") && updateBuilder({ ...data.builder, roles: data.builder.roles.filter((x) => x.id !== role.id) }, "Удаление", "Роль", role.id, "Роль удалена")}>Удалить</button></Actions></td></tr>)}</Table></>}
  {mode === "history" && <><PageHead title="История изменений" text="Все действия конструктора фиксируются и не исчезают при архивировании объектов." />{data.audit.length === 0 ? <Empty text="Изменений пока нет." /> : <Table headers={["Дата", "Пользователь", "Действие", "Объект", "Описание"]}>{data.audit.map((row) => <tr key={row.id}><td>{row.at}</td><td>{row.actor}</td><td>{row.action}</td><td>{row.entity}<small>{row.entityId}</small></td><td>{row.details}</td></tr>)}</Table>}</>}
  {mode === "backup" && <div className={styles.grid2}><Panel title="Резервная копия"><p>Экспорт содержит настройки, конструктор, формы, записи и историю.</p><Actions><button onClick={exportData}>Скачать JSON</button><label className={styles.fileButton}>Загрузить JSON<input type="file" accept="application/json" onChange={(e) => e.target.files?.[0] && importData(e.target.files[0])} /></label></Actions></Panel><Panel title="Полные права администратора"><ul className={styles.checkList}><li>Добавление, редактирование и удаление вкладок</li><li>Создание разделов, форм, таблиц и полей</li><li>Настройка кнопок и пользовательских действий</li><li>Создание ролей и наборов прав</li><li>Архив и восстановление элементов</li><li>Журнал всех изменений</li></ul></Panel></div>}
  </section>;
}

function CustomTabPage({ tab, data, open, updateBuilder, exportData, notice }: { tab: BuilderTab; data: DataState; open: (m: ModalState) => void; updateBuilder: (next: BuilderState, action: string, entity: string, entityId: string, details: string) => void; exportData: () => void; notice: (s: string) => void }) {
  const sections = sorted(data.builder.sections.filter((x) => x.tabId === tab.id && x.visible && !x.archived));
  const actions = sorted(data.builder.actions.filter((x) => x.tabId === tab.id && x.visible && !x.archived));
  function runAction(action: BuilderAction) { const first = sections[0]; if (action.confirmation && !confirm(action.confirmation)) return; if (action.type === "add" && first) open({ kind: "custom-record", parentId: first.id }); else if (action.type === "export") exportData(); else notice(`Выполнено действие: ${action.label}`); }
  return <section className={styles.page}><PageHead title={tab.label} text="Пользовательская вкладка, полностью созданная администратором в конструкторе." />{actions.length > 0 ? <div className={styles.customActions}>{actions.map((action) => <button key={action.id} onClick={() => runAction(action)}>{action.label}</button>)}</div> : null}{sections.length === 0 ? <Empty text="Вкладка создана, но в ней ещё нет разделов. Добавьте их в конструкторе." /> : sections.map((section) => <CustomSection key={section.id} section={section} data={data} open={open} updateBuilder={updateBuilder} />)}</section>;
}
function CustomSection({ section, data, open, updateBuilder }: { section: BuilderSection; data: DataState; open: (m: ModalState) => void; updateBuilder: (next: BuilderState, action: string, entity: string, entityId: string, details: string) => void }) {
  const fields = sorted(data.builder.fields.filter((x) => x.sectionId === section.id && x.visible && !x.archived));
  const records = data.builder.records.filter((x) => x.sectionId === section.id && !x.archived);
  if (section.type === "dashboard") return <Panel title={section.title}><p>{section.description}</p><div className={styles.cards}><Metric label="Записей" value={String(records.length)} /><Metric label="Полей" value={String(fields.length)} /></div><button className={styles.primarySmall} onClick={() => open({ kind: "custom-record", parentId: section.id })}>Добавить запись</button></Panel>;
  return <Panel title={section.title}><p>{section.description}</p><button className={styles.primarySmall} onClick={() => open({ kind: "custom-record", parentId: section.id })}>Добавить запись</button>{records.length === 0 ? <Empty text="Записей пока нет." /> : <Table headers={[...fields.map((x) => x.label), "Действия"]}>{records.map((record) => <tr key={record.id}>{fields.map((field) => <td key={field.id}>{typeof record.values[field.key] === "boolean" ? record.values[field.key] ? "Да" : "Нет" : String(record.values[field.key] ?? "")}</td>)}<td><Actions><button onClick={() => open({ kind: "custom-record", id: record.id, parentId: section.id })}>Изменить</button><button className={styles.dangerButton} onClick={() => updateBuilder({ ...data.builder, records: data.builder.records.map((x) => x.id === record.id ? { ...x, archived: true } : x) }, "Удаление в архив", "Запись", record.id, "Запись пользовательского раздела отправлена в архив")}>Удалить</button></Actions></td></tr>)}</Table>}</Panel>;
}

function EditorModal({ modal, data, close, update, updateBuilder, notice }: { modal: ModalState; data: DataState; close: () => void; update: <K extends keyof DataState>(k: K, v: DataState[K]) => void; updateBuilder: (next: BuilderState, action: string, entity: string, entityId: string, details: string) => void; notice: (s: string) => void }) {
  const request = data.requests.find((x) => x.id === modal.id); const user = data.users.find((x) => x.id === modal.id); const place = data.places.find((x) => x.id === modal.id); const tariff = data.tariffs.find((x) => x.id === modal.id); const template = data.templates.find((x) => x.id === modal.id); const route = data.routes.find((x) => x.id === modal.id); const monthly = data.monthly.find((x) => x.id === modal.id) || data.monthly[0];
  const builderTab = data.builder.tabs.find((x) => x.id === modal.id); const section = data.builder.sections.find((x) => x.id === modal.id); const field = data.builder.fields.find((x) => x.id === modal.id); const action = data.builder.actions.find((x) => x.id === modal.id); const role = data.builder.roles.find((x) => x.id === modal.id); const customRecord = data.builder.records.find((x) => x.id === modal.id); const customFields = sorted(data.builder.fields.filter((x) => x.sectionId === modal.parentId && x.visible && !x.archived));
  if (modal.kind === "preview" && template) return <Modal title={`Просмотр: ${template.name}`} close={close}><div className={styles.preview}><h2>{template.name}</h2><p>Тип: {template.type}</p><p>Версия: {template.version}</p><p>Действует с: {template.effectiveFrom}</p>{template.dataUrl && template.mimeType.includes("pdf") ? <iframe src={template.dataUrl} title={template.name} /> : <div className={styles.docPreview}><strong>{template.fileName || "Файл не загружен"}</strong><p>{template.fileName ? "DOCX сохранён в карточке шаблона." : "Загрузите официальный DOCX или PDF."}</p>{template.dataUrl ? <a href={template.dataUrl} download={template.fileName}>Открыть исходный файл</a> : null}</div>}</div></Modal>;
  function submit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); const form = new FormData(e.currentTarget);
    if (modal.kind === "request") { const row: RequestRow = { id: request?.id || uid("req"), number: s(form.get("number")) || `ЗГ-${String(data.requests.length + 1).padStart(4, "0")}`, author: s(form.get("author")), route: s(form.get("route")), purpose: s(form.get("purpose")), departureAt: s(form.get("departureAt")), returnAt: s(form.get("returnAt")), driver: s(form.get("driver")), vehicle: s(form.get("vehicle")), status: (s(form.get("status")) || "Черновик") as RequestStatus, returnReason: request?.returnReason || "", createdAt: request?.createdAt || new Date().toLocaleString("ru-RU"), docs: request?.docs || [] }; update("requests", request ? data.requests.map((x) => x.id === row.id ? row : x) : [row, ...data.requests]); }
    if (modal.kind === "user") { const row: UserRow = { id: user?.id || uid("user"), name: s(form.get("name")), login: s(form.get("login")), role: s(form.get("role")), active: form.get("active") === "on", terminationDate: s(form.get("terminationDate")), archived: form.get("archived") === "on" }; update("users", user ? data.users.map((x) => x.id === row.id ? row : x) : [row, ...data.users]); }
    if (modal.kind === "place") { const row: PlaceRow = { id: place?.id || uid("place"), name: s(form.get("name")), category: s(form.get("category")), manual: form.get("manual") === "on", active: form.get("active") === "on" }; update("places", place ? data.places.map((x) => x.id === row.id ? row : x) : [row, ...data.places]); }
    if (modal.kind === "tariff") { const row: TariffRow = { id: tariff?.id || uid("tariff"), name: s(form.get("name")), category: s(form.get("category")), dayRate: n(form.get("dayRate")), nightRate: n(form.get("nightRate")), oneDayRate: n(form.get("oneDayRate")), active: form.get("active") === "on" }; update("tariffs", tariff ? data.tariffs.map((x) => x.id === row.id ? row : x) : [row, ...data.tariffs]); }
    if (modal.kind === "route") { const row: RouteRow = { id: route?.id || uid("route"), name: s(form.get("name")), loadingPoint: s(form.get("loadingPoint")), unloadingPoint: s(form.get("unloadingPoint")), distance: n(form.get("distance")), manual: form.get("manual") === "on", active: form.get("active") === "on" }; update("routes", route ? data.routes.map((x) => x.id === row.id ? row : x) : [row, ...data.routes]); }
    if (modal.kind === "settings") update("settings", { company: s(form.get("company")), vehicle: s(form.get("vehicle")), mrp: n(form.get("mrp")), oneDayMrp: n(form.get("oneDayMrp")), overnightDayMrp: n(form.get("overnightDayMrp")), overnightNightMrp: n(form.get("overnightNightMrp")) });
    if (modal.kind === "monthly" && monthly) { const row: MonthlyRow = { id: monthly.id, month: s(form.get("month")), mileage: n(form.get("mileage")), fuel: n(form.get("fuel")), fuelPrice: n(form.get("fuelPrice")), wages: n(form.get("wages")), leasing: n(form.get("leasing")), repairs: n(form.get("repairs")), insurance: n(form.get("insurance")), tyres: n(form.get("tyres")), consumables: n(form.get("consumables")), idleHours: n(form.get("idleHours")), idlePrice: n(form.get("idlePrice")) }; update("monthly", data.monthly.map((x) => x.id === row.id ? row : x)); }
    if (modal.kind === "builder-tab") { const row: BuilderTab = { id: builderTab?.id || uid("tab"), label: s(form.get("label")), systemTarget: (s(form.get("systemTarget")) || undefined) as SystemTab | undefined, visible: form.get("visible") === "on", archived: form.get("archived") === "on", order: builderTab?.order ?? data.builder.tabs.length }; updateBuilder({ ...data.builder, tabs: builderTab ? data.builder.tabs.map((x) => x.id === row.id ? row : x) : [...data.builder.tabs, row] }, builderTab ? "Редактирование" : "Создание", "Вкладка", row.id, row.label); }
    if (modal.kind === "builder-section") { const row: BuilderSection = { id: section?.id || uid("section"), tabId: modal.parentId || section?.tabId || "", title: s(form.get("title")), description: s(form.get("description")), type: s(form.get("type")) as SectionType, visible: form.get("visible") === "on", archived: form.get("archived") === "on", order: section?.order ?? data.builder.sections.filter((x) => x.tabId === modal.parentId).length }; updateBuilder({ ...data.builder, sections: section ? data.builder.sections.map((x) => x.id === row.id ? row : x) : [...data.builder.sections, row] }, section ? "Редактирование" : "Создание", "Раздел", row.id, row.title); }
    if (modal.kind === "builder-field") { const row: BuilderField = { id: field?.id || uid("field"), sectionId: modal.parentId || field?.sectionId || "", label: s(form.get("label")), key: s(form.get("key")) || uid("value"), type: s(form.get("type")) as FieldType, required: form.get("required") === "on", visible: form.get("visible") === "on", archived: form.get("archived") === "on", order: field?.order ?? data.builder.fields.filter((x) => x.sectionId === modal.parentId).length, options: s(form.get("options")).split(",").map((x) => x.trim()).filter(Boolean) }; updateBuilder({ ...data.builder, fields: field ? data.builder.fields.map((x) => x.id === row.id ? row : x) : [...data.builder.fields, row] }, field ? "Редактирование" : "Создание", "Поле", row.id, row.label); }
    if (modal.kind === "builder-action") { const row: BuilderAction = { id: action?.id || uid("action"), tabId: modal.parentId || action?.tabId || "", label: s(form.get("label")), type: s(form.get("type")) as ActionType, visible: form.get("visible") === "on", archived: form.get("archived") === "on", order: action?.order ?? data.builder.actions.filter((x) => x.tabId === modal.parentId).length, confirmation: s(form.get("confirmation")) }; updateBuilder({ ...data.builder, actions: action ? data.builder.actions.map((x) => x.id === row.id ? row : x) : [...data.builder.actions, row] }, action ? "Редактирование" : "Создание", "Кнопка", row.id, row.label); }
    if (modal.kind === "builder-role") { const row: BuilderRole = { id: role?.id || uid("role"), name: s(form.get("name")), active: form.get("active") === "on", permissions: s(form.get("permissions")).split(",").map((x) => x.trim()).filter(Boolean) }; updateBuilder({ ...data.builder, roles: role ? data.builder.roles.map((x) => x.id === row.id ? row : x) : [...data.builder.roles, row] }, role ? "Редактирование" : "Создание", "Роль", row.id, row.name); }
    if (modal.kind === "custom-record") { const values: Record<string, string | number | boolean> = {}; customFields.forEach((f) => { const value = form.get(`field-${f.id}`); values[f.key] = f.type === "number" ? n(value) : f.type === "checkbox" ? value === "on" : s(value); }); const row: CustomRecord = { id: customRecord?.id || uid("record"), sectionId: modal.parentId || customRecord?.sectionId || "", values, createdAt: customRecord?.createdAt || new Date().toLocaleString("ru-RU"), updatedAt: new Date().toLocaleString("ru-RU"), archived: false }; updateBuilder({ ...data.builder, records: customRecord ? data.builder.records.map((x) => x.id === row.id ? row : x) : [row, ...data.builder.records] }, customRecord ? "Редактирование" : "Создание", "Запись", row.id, `Раздел ${row.sectionId}`); }
    if (modal.kind !== "template") { notice("Изменения сохранены"); close(); }
  }
  async function saveTemplate(e: FormEvent<HTMLFormElement>) { e.preventDefault(); const form = new FormData(e.currentTarget); const file = form.get("file") as File | null; let dataUrl = template?.dataUrl || ""; let fileName = template?.fileName || ""; let mimeType = template?.mimeType || ""; if (file && file.size > 0) { if (file.size > 3_000_000) return alert("Загрузите файл до 3 МБ."); dataUrl = await new Promise<string>((resolve) => { const r = new FileReader(); r.onload = () => resolve(String(r.result)); r.readAsDataURL(file); }); fileName = file.name; mimeType = file.type; } const row: TemplateRow = { id: template?.id || uid("tpl"), name: s(form.get("name")), type: s(form.get("type")), version: s(form.get("version")), effectiveFrom: s(form.get("effectiveFrom")), active: form.get("active") === "on", fileName, mimeType, dataUrl, usedCount: template?.usedCount || 0 }; update("templates", template ? data.templates.map((x) => x.id === row.id ? row : x) : [row, ...data.templates]); notice("Официальный бланк сохранён"); close(); }
  const title = modal.id ? "Редактирование" : "Добавление";
  return <Modal title={title} close={close}><form className={styles.form} onSubmit={modal.kind === "template" ? saveTemplate : submit}>
    {modal.kind === "request" && <><Field label="Номер"><input name="number" defaultValue={request?.number} placeholder="Автоматически" /></Field><Field label="Автор"><select name="author" defaultValue={request?.author || activeName(data.users, "Диспетчер")}><option value="">Выберите</option>{data.users.filter((x) => x.active).map((x) => <option key={x.id}>{x.name}</option>)}</select></Field><Field label="Маршрут"><input name="route" required defaultValue={request?.route} /></Field><Field label="Цель поездки"><textarea name="purpose" required defaultValue={request?.purpose} /></Field><div className={styles.formGrid}><Field label="Выезд"><input type="datetime-local" name="departureAt" required defaultValue={request?.departureAt || nowLocal()} /></Field><Field label="Возвращение"><input type="datetime-local" name="returnAt" required defaultValue={request?.returnAt || nowLocal()} /></Field></div><div className={styles.formGrid}><Field label="Водитель"><select name="driver" defaultValue={request?.driver}><option value="">Не назначен</option>{data.users.filter((x) => x.active && x.role === "Водитель").map((x) => <option key={x.id}>{x.name}</option>)}</select></Field><Field label="Автомобиль"><input name="vehicle" defaultValue={request?.vehicle || data.settings.vehicle} /></Field></div><Field label="Статус"><select name="status" defaultValue={request?.status || "Черновик"}>{["Черновик", "На согласовании", "Возвращена", "Согласована", "Завершена"].map((x) => <option key={x}>{x}</option>)}</select></Field></>}
    {modal.kind === "user" && <><Field label="ФИО"><input name="name" required defaultValue={user?.name} /></Field><div className={styles.formGrid}><Field label="Логин"><input name="login" required defaultValue={user?.login} /></Field><Field label="Роль"><select name="role" defaultValue={user?.role || "Заявитель"}>{data.builder.roles.map((x) => <option key={x.id}>{x.name}</option>)}</select></Field></div><Field label="Дата увольнения"><input type="date" name="terminationDate" defaultValue={user?.terminationDate} /></Field><Checks><label><input type="checkbox" name="active" defaultChecked={user?.active ?? true} />Активен</label><label><input type="checkbox" name="archived" defaultChecked={user?.archived} />Архивный</label></Checks></>}
    {modal.kind === "place" && <><Field label="Название"><input name="name" required defaultValue={place?.name} /></Field><Field label="Категория города / пункта"><select name="category" defaultValue={place?.category || "Город областного значения"}>{["Город республиканского значения", "Город областного значения", "Город районного значения", "Населённый пункт"].map((x) => <option key={x}>{x}</option>)}</select></Field><Checks><label><input type="checkbox" name="manual" defaultChecked={place?.manual ?? true} />Добавлен вручную</label><label><input type="checkbox" name="active" defaultChecked={place?.active ?? true} />Активен</label></Checks></>}
    {modal.kind === "tariff" && <><Field label="Название"><input name="name" required defaultValue={tariff?.name} /></Field><Field label="Категория"><input name="category" required defaultValue={tariff?.category} /></Field><div className={styles.formGrid3}><Field label="День, МРП"><input type="number" step="any" name="dayRate" defaultValue={tariff?.dayRate} /></Field><Field label="Ночь, МРП"><input type="number" step="any" name="nightRate" defaultValue={tariff?.nightRate} /></Field><Field label="Однодневная, МРП"><input type="number" step="any" name="oneDayRate" defaultValue={tariff?.oneDayRate} /></Field></div><Checks><label><input type="checkbox" name="active" defaultChecked={tariff?.active ?? true} />Активен</label></Checks></>}
    {modal.kind === "route" && <><Field label="Название маршрута"><input name="name" required defaultValue={route?.name} /></Field><div className={styles.formGrid}><Field label="Пункт загрузки"><input name="loadingPoint" required defaultValue={route?.loadingPoint} /></Field><Field label="Пункт выгрузки"><input name="unloadingPoint" required defaultValue={route?.unloadingPoint} /></Field></div><Field label="Расстояние, км"><input type="number" step="any" name="distance" defaultValue={route?.distance} /></Field><Checks><label><input type="checkbox" name="manual" defaultChecked={route?.manual} />Введён вручную</label><label><input type="checkbox" name="active" defaultChecked={route?.active ?? true} />Активен</label></Checks></>}
    {modal.kind === "settings" && <><Field label="Компания"><input name="company" defaultValue={data.settings.company} /></Field><Field label="Автомобиль"><input name="vehicle" defaultValue={data.settings.vehicle} /></Field><div className={styles.formGrid}><Field label="МРП"><input type="number" step="any" name="mrp" defaultValue={data.settings.mrp} /></Field><Field label="Однодневная поездка, МРП"><input type="number" step="any" name="oneDayMrp" defaultValue={data.settings.oneDayMrp} /></Field><Field label="День с ночёвкой, МРП"><input type="number" step="any" name="overnightDayMrp" defaultValue={data.settings.overnightDayMrp} /></Field><Field label="Ночь, МРП"><input type="number" step="any" name="overnightNightMrp" defaultValue={data.settings.overnightNightMrp} /></Field></div></>}
    {modal.kind === "monthly" && monthly && <><Field label="Месяц"><input type="month" name="month" defaultValue={monthly.month} /></Field><div className={styles.formGrid3}>{[["mileage","Пробег"],["fuel","Топливо"],["fuelPrice","Цена топлива"],["wages","Зарплата"],["leasing","Лизинг"],["repairs","Ремонты"],["insurance","Страхование"],["tyres","Шины"],["consumables","Расходники"],["idleHours","Простой, ч"],["idlePrice","Цена простоя"]].map(([name,label]) => <Field key={name} label={label}><input type="number" step="any" name={name} defaultValue={monthly[name as keyof MonthlyRow] as number} /></Field>)}</div></>}
    {modal.kind === "template" && <><Field label="Своё название"><input name="name" required defaultValue={template?.name} /></Field><div className={styles.formGrid}><Field label="Вид документа"><input name="type" required defaultValue={template?.type} /></Field><Field label="Версия"><input name="version" required defaultValue={template?.version || "1.0"} /></Field></div><Field label="Дата начала действия"><input type="date" name="effectiveFrom" defaultValue={template?.effectiveFrom || today} /></Field><Field label="Официальный DOCX или PDF"><input type="file" name="file" accept=".docx,.pdf,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" /><small>{template?.fileName ? `Текущий файл: ${template.fileName}` : "Файл ещё не загружен"}</small></Field><Checks><label><input type="checkbox" name="active" defaultChecked={template?.active ?? true} />Действующий шаблон</label></Checks></>}
    {modal.kind === "builder-tab" && <><Field label="Название вкладки"><input name="label" required defaultValue={builderTab?.label} /></Field><Field label="Системный экран"><select name="systemTarget" defaultValue={builderTab?.systemTarget || ""}><option value="">Пользовательская вкладка</option>{systemTabs.map((x) => <option key={x.id} value={x.id}>{x.label}</option>)}</select><small>Для новой самостоятельной вкладки оставьте «Пользовательская».</small></Field><Checks><label><input type="checkbox" name="visible" defaultChecked={builderTab?.visible ?? true} />Показывать в меню</label><label><input type="checkbox" name="archived" defaultChecked={builderTab?.archived} />Архив</label></Checks></>}
    {modal.kind === "builder-section" && <><Field label="Название раздела"><input name="title" required defaultValue={section?.title} /></Field><Field label="Описание"><textarea name="description" defaultValue={section?.description} /></Field><Field label="Тип раздела"><select name="type" defaultValue={section?.type || "table"}><option value="table">Таблица записей</option><option value="form">Форма</option><option value="dashboard">Информационный блок</option></select></Field><Checks><label><input type="checkbox" name="visible" defaultChecked={section?.visible ?? true} />Показывать</label><label><input type="checkbox" name="archived" defaultChecked={section?.archived} />Архив</label></Checks></>}
    {modal.kind === "builder-field" && <><Field label="Название поля"><input name="label" required defaultValue={field?.label} /></Field><Field label="Системный ключ"><input name="key" defaultValue={field?.key} placeholder="например: destination" /><small>Используется для хранения значения.</small></Field><Field label="Тип поля"><select name="type" defaultValue={field?.type || "text"}>{[["text","Текст"],["number","Число"],["date","Дата"],["datetime","Дата и время"],["textarea","Большой текст"],["select","Список"],["checkbox","Галочка"]].map(([value,label]) => <option key={value} value={value}>{label}</option>)}</select></Field><Field label="Варианты списка через запятую"><input name="options" defaultValue={field?.options.join(", ")} /></Field><Checks><label><input type="checkbox" name="required" defaultChecked={field?.required} />Обязательное</label><label><input type="checkbox" name="visible" defaultChecked={field?.visible ?? true} />Показывать</label><label><input type="checkbox" name="archived" defaultChecked={field?.archived} />Архив</label></Checks></>}
    {modal.kind === "builder-action" && <><Field label="Название кнопки"><input name="label" required defaultValue={action?.label} /></Field><Field label="Действие"><select name="type" defaultValue={action?.type || "add"}><option value="add">Добавить запись</option><option value="export">Экспорт данных</option><option value="custom">Пользовательское действие</option></select></Field><Field label="Текст подтверждения"><input name="confirmation" defaultValue={action?.confirmation} placeholder="Оставьте пустым, если подтверждение не нужно" /></Field><Checks><label><input type="checkbox" name="visible" defaultChecked={action?.visible ?? true} />Показывать</label><label><input type="checkbox" name="archived" defaultChecked={action?.archived} />Архив</label></Checks></>}
    {modal.kind === "builder-role" && <><Field label="Название роли"><input name="name" required defaultValue={role?.name} /></Field><Field label="Разрешения через запятую"><textarea name="permissions" defaultValue={role?.permissions.join(", ")} placeholder="view, create, edit, delete, approve" /></Field><Checks><label><input type="checkbox" name="active" defaultChecked={role?.active ?? true} />Активна</label></Checks></>}
    {modal.kind === "custom-record" && <>{customFields.length === 0 ? <Empty text="В разделе нет полей. Сначала добавьте поля в конструкторе." /> : customFields.map((f) => <Field key={f.id} label={f.label}>{renderCustomInput(f, customRecord?.values[f.key])}</Field>)}</>}
    <div className={styles.modalActions}><button type="button" className={styles.secondary} onClick={close}>Отмена</button><button className={styles.primary} disabled={modal.kind === "custom-record" && customFields.length === 0}>Сохранить</button></div>
  </form></Modal>;
}
function renderCustomInput(field: BuilderField, value: string | number | boolean | undefined) {
  const name = `field-${field.id}`;
  if (field.type === "textarea") return <textarea name={name} required={field.required} defaultValue={String(value ?? "")} />;
  if (field.type === "select") return <select name={name} required={field.required} defaultValue={String(value ?? "")}><option value="">Выберите</option>{field.options.map((x) => <option key={x}>{x}</option>)}</select>;
  if (field.type === "checkbox") return <input type="checkbox" name={name} defaultChecked={Boolean(value)} />;
  return <input type={field.type === "datetime" ? "datetime-local" : field.type} name={name} required={field.required} step={field.type === "number" ? "any" : undefined} defaultValue={typeof value === "boolean" ? "" : String(value ?? "")} />;
}
function activeName(users: UserRow[], role: string) { return users.find((x) => x.active && x.role === role)?.name || ""; }
function PageHead({ title, text, action, onAction }: { title: string; text: string; action?: string; onAction?: () => void }) { return <div className={styles.pageHead}><div><h2>{title}</h2><p>{text}</p></div>{action ? <button className={styles.primary} onClick={onAction}>{action}</button> : null}</div>; }
function Metric({ label, value, tone }: { label: string; value: string; tone?: "normal" | "warning" }) { return <div className={`${styles.metric} ${tone === "warning" ? styles.metricWarning : ""}`}><span>{label}</span><strong>{value}</strong></div>; }
function Status({ label, value }: { label: string; value: string }) { return <div className={styles.status}><span>{label}</span><strong>{value}</strong></div>; }
function Panel({ title, children }: { title: string; children: ReactNode }) { return <div className={styles.panel}><h2>{title}</h2>{children}</div>; }
function Table({ headers, children }: { headers: string[]; children: ReactNode }) { return <div className={styles.tableWrap}><table><thead><tr>{headers.map((x) => <th key={x}>{x}</th>)}</tr></thead><tbody>{children}</tbody></table></div>; }
function Actions({ children }: { children: ReactNode }) { return <div className={styles.actions}>{children}</div>; }
function Checks({ children }: { children: ReactNode }) { return <div className={styles.checks}>{children}</div>; }
function Field({ label, children }: { label: string; children: ReactNode }) { return <label className={styles.field}><span>{label}</span>{children}</label>; }
function Empty({ text }: { text: string }) { return <div className={styles.empty}>{text}</div>; }
function Badge({ status }: { status: RequestStatus }) { const cls = status === "Согласована" || status === "Завершена" ? styles.badgeOk : status === "Возвращена" ? styles.badgeBad : status === "На согласовании" ? styles.badgeWait : ""; return <span className={`${styles.badge} ${cls}`}>{status}</span>; }
function Modal({ title, close, children }: { title: string; close: () => void; children: ReactNode }) { return <div className={styles.modalBackdrop} onMouseDown={(e) => e.target === e.currentTarget && close()}><div className={styles.modal}><div className={styles.modalHeader}><h2>{title}</h2><button onClick={close} aria-label="Закрыть">×</button></div>{children}</div></div>; }
